def lcs_prefix_back(a, b, tie):  # prefix DP, traceback from end
    n, m = len(a), len(b)
    L = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n):
        for j in range(m):
            L[i+1][j+1] = L[i][j]+1 if a[i]==b[j] else max(L[i][j+1], L[i+1][j])
    i, j = n, m; out = []; path=[]
