        for j in range(M):
            if b[j] == a[i]:
                idx[i*M+j] = 1 if (i == 0 or j == 0) else idx[(i-1)*M+j-1]+1
            elif i == 0:
                idx[i*M+j] = 0 if j == 0 else idx[i*M+j-1]
            elif j == 0:
