//! it compares against the cell located just before the current one in the
//! flattened table, which is the behaviour the output highlighting relies on.

/// A chunk of a computed difference.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Chunk {
    Same(String),
    Add(String),
    Rem(String),
}

fn common_chars(orig: &[char], edit: &[char]) -> Vec<char> {
    let n = orig.len();
    let m = edit.len();
    if n == 0 || m == 0 {
        return Vec::new();
    }
    let mut table = vec![0usize; n * m];
    for i in 0..n {
        for j in 0..m {
            let pos = i * m + j;
            table[pos] = if edit[j] == orig[i] {
                if i == 0 || j == 0 {
                    1
                } else {
                    table[(i - 1) * m + j - 1] + 1
                }
            } else if i == 0 {
                if j == 0 {
                    0
                } else {
                    table[pos - 1]
                }
            } else if j == 0 {
                table[(i - 1) * m + j]
            } else {
                std::cmp::max(table[pos - 1], table[(i - 1) * m + j])
            };
        }
    }

    let mut i = n as isize - 1;
    let mut j = m as isize - 1;
    let mut common = Vec::new();
    while i >= 0 && j >= 0 {
        let ui = i as usize;
        let uj = j as usize;
        if orig[ui] == edit[uj] {
            common.push(orig[ui]);
            i -= 1;
            j -= 1;
        } else if i == 0 && j == 0 {
            break;
        } else if i == 0 || table[(ui * m + uj).wrapping_sub(1) % (n * m)] > table[(ui - 1) * m + uj] {
            j -= 1;
        } else {
            i -= 1;
        }
    }
    common.reverse();
    common
}

fn push(chunks: &mut Vec<Chunk>, chunk: Chunk) {
    match (chunks.last_mut(), &chunk) {
        (Some(Chunk::Same(prev)), Chunk::Same(s)) => prev.push_str(s),
        (Some(Chunk::Add(prev)), Chunk::Add(s)) => prev.push_str(s),
        (Some(Chunk::Rem(prev)), Chunk::Rem(s)) => prev.push_str(s),
        _ => chunks.push(chunk),
    }
}

/// Compute the differences needed to transform `orig` into `edit`.
pub fn diff(orig: &str, edit: &str) -> Vec<Chunk> {
    let a: Vec<char> = orig.chars().collect();
    let b: Vec<char> = edit.chars().collect();
    let common = common_chars(&a, &b);

    let mut chunks = Vec::new();
    let mut ia = 0;
    let mut ib = 0;
    for c in common {
        let mut removed = String::new();
        while ia < a.len() && a[ia] != c {
            removed.push(a[ia]);
            ia += 1;
        }
        ia += 1;
        if !removed.is_empty() {
            push(&mut chunks, Chunk::Rem(removed));
        }
        let mut added = String::new();
        while ib < b.len() && b[ib] != c {
            added.push(b[ib]);
            ib += 1;
        }
        ib += 1;
        if !added.is_empty() {
            push(&mut chunks, Chunk::Add(added));
        }
        push(&mut chunks, Chunk::Same(c.to_string()));
    }
    if ia < a.len() {
        push(&mut chunks, Chunk::Rem(a[ia..].iter().collect()));
    }
    if ib < b.len() {
        push(&mut chunks, Chunk::Add(b[ib..].iter().collect()));
    }
    chunks
}
