use crate::diff::{diff, Chunk};
use crate::error::{Error, ErrorKind};
use std::path::Path;

const BOLD: &str = "1";
const DIMMED: &str = "38;5;8";
const GREEN: &str = "32";
const RED: &str = "31";
const BOLD_RED: &str = "1;31";

/// Printing mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PrinterMode {
    Silent,
    NoColor,
    Color,
}

/// Printer used to report information to the user.
#[derive(Debug, Clone, Copy)]
pub struct Printer {
    pub mode: PrinterMode,
}

impl Printer {
    /// Printer with colored output.
    pub fn color() -> Printer {
        Printer {
            mode: PrinterMode::Color,
        }
    }

    /// Printer without colors.
    pub fn no_color() -> Printer {
        Printer {
            mode: PrinterMode::NoColor,
        }
    }

    /// Printer that does not print anything.
    pub fn silent() -> Printer {
        Printer {
            mode: PrinterMode::Silent,
        }
    }

    fn colored(&self) -> bool {
        self.mode == PrinterMode::Color
    }

    /// Paint the given text with a style if colors are enabled.
    pub fn paint(&self, style: &str, text: &str) -> String {
        if self.colored() {
            format!("\x1b[{}m{}\x1b[0m", style, text)
        } else {
            text.to_string()
        }
    }

    /// Paint text in red.
    pub fn red(&self, text: &str) -> String {
        self.paint(RED, text)
    }

    /// Print a line to the standard output.
    pub fn print(&self, message: &str) {
        if self.mode != PrinterMode::Silent {
            println!("{}", message);
        }
    }

    /// Print a line to the standard error.
    pub fn eprint(&self, message: &str) {
        if self.mode != PrinterMode::Silent {
            eprintln!("{}", message);
        }
    }

    /// Print the dry-run banner.
    pub fn print_dry_run(&self) {
        let banner = self.paint(BOLD, "This is a DRY-RUN");
        self.print(&banner);
    }

    /// Format an error message.
    pub fn format_error(&self, error: &Error) -> String {
        let value = match error.value {
            Some(ref value) => value.clone(),
            None => String::new(),
        };
        format!(
            "{}{}{}",
            self.red("Error: "),
            error.description(),
            self.red(&value)
        )
    }

    /// Print an error to the standard error.
    pub fn print_error(&self, error: &Error) {
        let message = self.format_error(error);
        self.eprint(&message);
    }

    /// Print an informative message about a created backup.
    pub fn print_backup(&self, source: &Path, backup: &Path) {
        let message = format!(
            "{} Backup created - {}",
            self.paint(BOLD, "Info: "),
            self.paint(DIMMED, &format!("{} -> {}", source.display(), backup.display()))
        );
        self.print(&message);
    }

    /// Whether error kinds ignore the silent mode.
    pub fn always_reported(kind: ErrorKind) -> bool {
        kind == ErrorKind::BadRegex
    }

    /// Print a rename operation, highlighting changes on the target name.
    pub fn print_operation(&self, source: &Path, target: &Path) {
        if self.mode == PrinterMode::Silent {
            return;
        }
        let mut source_parent = source.parent().unwrap().to_string_lossy().to_string();
        let mut source_name = source.file_name().unwrap().to_string_lossy().to_string();
        let mut target_parent = target.parent().unwrap().to_string_lossy().to_string();
        let mut target_name = target.file_name().unwrap().to_string_lossy().to_string();

        if !source_parent.is_empty() {
            source_parent.push('/');
        }
        if !target_parent.is_empty() {
            target_parent.push('/');
        }

        if self.colored() {
            let changes = diff(&source_name, &target_name);
            let mut highlighted = String::new();
            for chunk in changes {
                match chunk {
                    Chunk::Same(text) => highlighted.push_str(&self.paint(GREEN, &text)),
                    Chunk::Add(text) => highlighted.push_str(&self.paint(BOLD_RED, &text)),
                    Chunk::Rem(_) => {}
                }
            }
            if !source_parent.is_empty() {
                source_parent = self.paint(DIMMED, &source_parent);
            }
            if !target_parent.is_empty() {
                target_parent = self.paint(GREEN, &target_parent);
            }
            source_name = self.paint(DIMMED, &source_name);
            target_name = highlighted;
        }

        self.print(&format!(
            "{}{} -> {}{}",
            source_parent, source_name, target_parent, target_name
        ));
    }
}
