//! File system helpers: directory traversal and backups.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};

/// Returns true when the given path exists, without following symlinks.
pub fn path_exists(path: &Path) -> bool {
    fs::symlink_metadata(path).is_ok()
}

/// Returns true when the file name starts with a dot.
fn is_hidden(name: &std::ffi::OsStr) -> bool {
    name.to_str().map(|s| s.starts_with('.')).unwrap_or(false)
}

/// Walk a directory tree starting at `root`, returning every entry found.
///
/// The root itself is always included (if it can be accessed), symbolic links
/// are only followed for the root, and unreadable entries are skipped.
pub fn walk(root: &Path, max_depth: Option<usize>, hidden: bool) -> Vec<PathBuf> {
    let mut entries = Vec::new();
    let metadata = match fs::metadata(root) {
        Ok(metadata) => metadata,
        Err(_) => return entries,
    };
    entries.push(root.to_path_buf());
    if metadata.is_dir() && max_depth.map_or(true, |max| max > 0) {
        walk_dir(root, 1, max_depth, hidden, &mut entries);
    }
    entries
}

fn walk_dir(dir: &Path, depth: usize, max: Option<usize>, hidden: bool, out: &mut Vec<PathBuf>) {
    let reader = match fs::read_dir(dir) {
        Ok(reader) => reader,
        Err(_) => return,
    };
    for entry in reader {
        let entry = match entry {
            Ok(entry) => entry,
            Err(_) => continue,
        };
        let name = entry.file_name();
        if !hidden && is_hidden(&name) {
            continue;
        }
        let file_type = match entry.file_type() {
            Ok(file_type) => file_type,
            Err(_) => continue,
        };
        let path = dir.join(&name);
        out.push(path.clone());
        if file_type.is_dir() && max.map_or(true, |max| depth < max) {
            walk_dir(&path, depth + 1, max, hidden, out);
        }
    }
}

/// Create a backup copy of the given file, returning the backup path.
pub fn create_backup(path: &Path) -> io::Result<PathBuf> {
    let base_name: String = String::from(path.file_name().unwrap().to_string_lossy());
    let mut backup = path.with_file_name(format!("{}.bk", base_name));
    let mut index = 1;
    while path_exists(&backup) {
        backup = path.with_file_name(format!("{}.bk.{}", base_name, index));
        index += 1;
    }
    fs::copy(path, &backup)?;
    Ok(backup)
}
