//! Unicode to ASCII transliteration.
//!
//! The transliteration table is stored as text: each line starts with the
//! hexadecimal code point of a run of consecutive characters, followed by the
//! tab separated replacement of every character in the run. Characters not
//! present in the table have an empty replacement.

use std::sync::OnceLock;

static TABLE_DATA: &str = include_str!("../data/ascii_table.txt");

struct Run {
    start: u32,
    values: Vec<&'static str>,
}

fn table() -> &'static Vec<Run> {
    static TABLE: OnceLock<Vec<Run>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let mut runs = Vec::new();
        for line in TABLE_DATA.split('\n') {
            if line.is_empty() {
                continue;
            }
            let mut fields = line.split('\t');
            let start = match fields.next().and_then(|h| u32::from_str_radix(h, 16).ok()) {
                Some(start) => start,
                None => continue,
            };
            runs.push(Run {
                start,
                values: fields.collect(),
            });
        }
        runs.sort_by_key(|run| run.start);
        runs
    })
}

fn lookup(c: char) -> &'static str {
    let code = c as u32;
    let runs = table();
    let index = match runs.binary_search_by_key(&code, |run| run.start) {
        Ok(index) => index,
        Err(0) => return "",
        Err(index) => index - 1,
    };
    let run = &runs[index];
    let offset = (code - run.start) as usize;
    run.values.get(offset).copied().unwrap_or("")
}

/// Transliterate a string to its ASCII representation.
pub fn to_ascii(text: &str) -> String {
    let mut result = String::with_capacity(text.len());
    for c in text.chars() {
        if c.is_ascii() {
            result.push(c);
        } else {
            result.push_str(lookup(c));
        }
    }
    result
}
