/// Broken down date and time.
#[derive(Debug, Clone, Copy)]
pub struct DateTime {
    pub year: i32,
    pub month: u32,
    pub day: u32,
    pub hour: u32,
    pub minute: u32,
    pub second: u32,
}

impl DateTime {
    /// Format as `YYYY-MM-DD HH:MM:SS`.
    pub fn format_date(&self) -> String {
        format!(
            "{:04}-{:02}-{:02} {:02}:{:02}:{:02}",
            self.year, self.month, self.day, self.hour, self.minute, self.second
        )
    }

    /// Format as `YYYY-MM-DD_HHMMSS`.
    pub fn format_file(&self) -> String {
        format!(
            "{:04}-{:02}-{:02}_{:02}{:02}{:02}",
            self.year, self.month, self.day, self.hour, self.minute, self.second
        )
    }
}

fn skip_name(bytes: &[u8], mut pos: usize) -> Option<usize> {
    if pos < bytes.len() && bytes[pos] == b'<' {
        while pos < bytes.len() && bytes[pos] != b'>' {
            pos += 1;
        }
        if pos >= bytes.len() {
            return None;
        }
        return Some(pos + 1);
    }
    let start = pos;
    while pos < bytes.len() && bytes[pos].is_ascii_alphabetic() {
        pos += 1;
    }
    if pos - start < 3 {
        return None;
    }
    Some(pos)
}

fn skip_offset(bytes: &[u8], mut pos: usize) -> usize {
    if pos < bytes.len() && (bytes[pos] == b'+' || bytes[pos] == b'-') {
        pos += 1;
    }
    while pos < bytes.len() && (bytes[pos].is_ascii_digit() || bytes[pos] == b':') {
        pos += 1;
    }
    pos
}

/// Some TZ values describing daylight saving time without explicit rules are
/// not supported: UTC is used for them.
fn unsupported_tz() -> bool {
    let tz = match std::env::var("TZ") {
        Ok(tz) => tz,
        Err(_) => return false,
    };
    let tz = tz.strip_prefix(':').unwrap_or(&tz);
    if tz.is_empty() {
        return false;
    }
    let file = if tz.starts_with('/') {
        std::path::PathBuf::from(tz)
    } else {
        std::path::Path::new("/usr/share/zoneinfo").join(tz)
    };
    if file.is_file() {
        return false;
    }
    let bytes = tz.as_bytes();
    let pos = match skip_name(bytes, 0) {
        Some(pos) => pos,
        None => return false,
    };
    let pos = skip_offset(bytes, pos);
    if pos >= bytes.len() {
        return false;
    }
    let pos = match skip_name(bytes, pos) {
        Some(pos) => pos,
        None => return false,
    };
    let pos = skip_offset(bytes, pos);
    pos >= bytes.len() || bytes[pos] != b','
}

/// Current local date and time.
pub fn now() -> DateTime {
    let secs = match SystemTime::now().duration_since(UNIX_EPOCH) {
        Ok(duration) => duration.as_secs() as i64,
        Err(_) => 0,
    };
    let mut tm = Tm {
        tm_sec: 0,
        tm_min: 0,
        tm_hour: 0,
        tm_mday: 1,
        tm_mon: 0,
        tm_year: 70,
        tm_wday: 0,
        tm_yday: 0,
        tm_isdst: 0,
        tm_gmtoff: 0,
        tm_zone: std::ptr::null(),
    };
    let utc = unsupported_tz();
    let result = unsafe {
        if utc {
            gmtime_r(&secs, &mut tm)
        } else {
            tzset();
            localtime_r(&secs, &mut tm)
        }
    };
    if result.is_null() {
        unsafe {
            gmtime_r(&secs, &mut tm);
        }
    }
    DateTime {
        year: tm.tm_year + 1900,
        month: (tm.tm_mon + 1) as u32,
        day: tm.tm_mday as u32,
        hour: tm.tm_hour as u32,
        minute: tm.tm_min as u32,
        second: tm.tm_sec as u32,
    }
}
