        while let Some(field) = map.next_key_seed(FieldSeed { names: OPERATION_FIELDS })? {
            match field {
                Field::Index(0) => {
                    if source.is_some() {
                        return Err(de::Error::duplicate_field("source"));
                    }
                    source = Some(map.next_value()?);
                }
                Field::Index(1) => {
                    if target.is_some() {
                        return Err(de::Error::duplicate_field("target"));
                    }
                    target = Some(map.next_value()?);
                }
                _ => {
                    let _: IgnoredAny = map.next_value()?;
                }
            }
        }
        let source = source.ok_or_else(|| de::Error::missing_field("source"))?;
        let target = target.ok_or_else(|| de::Error::missing_field("target"))?;
        Ok(DumpOperation { source, target })
    }
}

impl<'de> Deserialize<'de> for DumpOperation {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> std::result::Result<Self, D::Error> {
        deserializer.deserialize_struct("Operation", OPERATION_FIELDS, OperationVisitor)
    }
}

struct DumpVisitor;

impl<'de> Visitor<'de> for DumpVisitor {
    type Value = DumpFormat;

    fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
        formatter.write_str("struct DumpFormat")
    }

    fn visit_seq<A: SeqAccess<'de>>(self, mut seq: A) -> std::result::Result<DumpFormat, A::Error> {
        let date: String = match seq.next_element()? {
            Some(value) => value,
            None => return Err(de::Error::invalid_length(0, &"struct DumpFormat with 2 elements")),
        };
        let operations: Vec<DumpOperation> = match seq.next_element()? {
            Some(value) => value,
            None => return Err(de::Error::invalid_length(1, &"struct DumpFormat with 2 elements")),
        };
        Ok(DumpFormat { date, operations })
    }

    fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> std::result::Result<DumpFormat, A::Error> {
        let mut date: Option<String> = None;
        let mut operations: Option<Vec<DumpOperation>> = None;
        while let Some(field) = map.next_key_seed(FieldSeed { names: DUMP_FIELDS })? {
            match field {
                Field::Index(0) => {
                    if date.is_some() {
                        return Err(de::Error::duplicate_field("date"));
                    }
                    date = Some(map.next_value()?);
                }
                Field::Index(1) => {
                    if operations.is_some() {
                        return Err(de::Error::duplicate_field("operations"));
                    }
                    operations = Some(map.next_value()?);
                }
                _ => {
                    let _: IgnoredAny = map.next_value()?;
                }
            }
        }
        let date = date.ok_or_else(|| de::Error::missing_field("date"))?;
        let operations = operations.ok_or_else(|| de::Error::missing_field("operations"))?;
        Ok(DumpFormat { date, operations })
    }
}

impl<'de> Deserialize<'de> for DumpFormat {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> std::result::Result<Self, D::Error> {
        deserializer.deserialize_struct("DumpFormat", DUMP_FIELDS, DumpVisitor)
    }
}

/// Write the operations into a new dump file named after the current time.
pub fn dump_to_file(prefix: &str, operations: &Operations) -> Result<()> {
    let now = localtime::now();
    let filename = format!("{}{}.json", prefix, now.format_file());
    let dump = DumpFormat {
        date: now.format_date(),
        operations: operations
            .iter()
            .map(|operation| DumpOperation {
                source: operation.source.to_string_lossy().to_string(),
                target: operation.target.to_string_lossy().to_string(),
            })
            .collect(),
    };
    let file = match File::create(&filename) {
        Ok(file) => file,
        Err(_) => return Err(Error::new(ErrorKind::CreateFile, Some(filename))),
    };
    match serde_json::to_writer_pretty(file, &dump) {
        Ok(_) => Ok(()),
        Err(_) => Err(Error::new(ErrorKind::CreateFile, Some(filename))),
    }
}

/// Read operations from a dump file.
pub fn read_from_file(path: &Path) -> Result<Operations> {
    let file = match File::open(path) {
        Ok(file) => file,
        Err(_) => {
            return Err(Error::new(
                ErrorKind::ReadFile,
                Some(path.to_string_lossy().to_string()),
            ))
        }
    };
    let dump: DumpFormat = match serde_json::from_reader(std::io::BufReader::new(file)) {
        Ok(dump) => dump,
        Err(_) => {
            return Err(Error::new(
                ErrorKind::JsonParse,
                Some(path.to_string_lossy().to_string()),
            ))
        }
    };
    let _ = dump.date;
    Ok(dump
        .operations
        .into_iter()
        .map(|operation| Operation {
            source: PathBuf::from(operation.source),
            target: PathBuf::from(operation.target),
        })
        .collect())
}
