cat > src/renamer.rs <<'EOF'
//! Execution of rename operations.

use crate::config::{Config, RunMode};
use crate::dumpfile;
use crate::error::{Error, ErrorKind, Result};
use crate::fileutils::create_backup;
use crate::operation::{Operation, Operations};
use crate::solver;
use std::fs;
use std::path::Path;

fn get_operations(config: &Config) -> Result<Operations> {
    match config.run_mode {
        RunMode::FromFile { ref path, undo } => {
            let operations = dumpfile::read_from_file(Path::new(path))?;
            if undo {
                Ok(operations
                    .into_iter()
                    .rev()
                    .map(|op| Operation {
                        source: op.target,
                        target: op.source,
                    })
                    .collect())
            } else {
                Ok(operations)
            }
        }
        _ => solver::solve(config),
    }
}

fn execute(config: &Config, operation: &Operation) -> Result<()> {
    let printer = &config.printer;
    if config.force {
        if config.backup && !operation.source.is_dir() {
            match create_backup(&operation.source) {
                Ok(backup) => printer.print_backup(&operation.source, &backup),
                Err(_) => {
                    return Err(Error::new(
                        ErrorKind::CreateBackup,
                        Some(operation.source.display().to_string()),
                    ))
                }
            }
        }
        if let Err(err) = fs::rename(&operation.source, &operation.target) {
            return Err(Error::new(
                ErrorKind::Rename,
                Some(format!(
                    "{} -> {}\n{}",
                    operation.source.display(),
                    operation.target.display(),
                    err
                )),
            ));
        }
    }
    printer.print_operation(&operation.source, &operation.target);
    Ok(())
}

/// Run the configured process.
pub fn run(config: &Config) -> Result<()> {
    if !config.force {
        config.printer.print_dry_run();
    }
    let operations = get_operations(config)?;
    if config.dump {
        dumpfile::dump_to_file(&config.dump_prefix, &operations)?;
    }
    for operation in &operations {
        execute(config, operation)?;
    }
    Ok(())
}
